from pydantic import BaseModel

logger = logging.getLogger(__name__)


class ToolDefinition(BaseModel):
    name: str
    description: str
    parameters_schema: Dict[str, Any]
    required_permissions: List[str] = []


class ToolSandbox:
    """
    Secure tool calling registry and sandbox.
    Executes functions with argument validation, timeout boundaries, and permission checks.
    """
    def __init__(self):
        self.tools: Dict[str, Callable[..., Awaitable[Any]]] = {}
        self.definitions: Dict[str, ToolDefinition] = {}

    def register_tool(
        self,
        name: str,
        description: str,
        parameters_schema: Dict[str, Any],
        handler: Callable[..., Awaitable[Any]],
        required_permissions: Optional[List[str]] = None
    ):
        self.tools[name] = handler
        self.definitions[name] = ToolDefinition(
            name=name,
            description=description,
            parameters_schema=parameters_schema,
            required_permissions=required_permissions or []
        )

    def get_openai_tools(self) -> List[Dict[str, Any]]:
        """Formats registered tools for OpenAI function calling."""
        return [
            {
                "type": "function",
                "function": {
                    "name": d.name,
                    "description": d.description,
                    "parameters": d.parameters_schema,
                }
            }
            for d in self.definitions.values()
        ]

    async def execute_tool(
        self,
        name: str,
        arguments: Dict[str, Any],
        user_permissions: List[str],
        timeout_seconds: float = 5.0
    ) -> Dict[str, Any]:
        """
        Executes a tool call inside a timeout boundary with permission verification.
        """
        if name not in self.tools:
            return {"error": f"Tool '{name}' not found."}

        defn = self.definitions[name]
        # Permission check
        for perm in defn.required_permissions:
            if perm not in user_permissions:
                return {"error": f"Permission denied for tool '{name}'. Required: {perm}"}

        handler = self.tools[name]
        try:
            result = await asyncio.wait_for(handler(**arguments), timeout=timeout_seconds)
            return {"result": result}
        except asyncio.TimeoutError:
            logger.error(f"Tool {name} execution timed out after {timeout_seconds}s")
            return {"error": f"Tool '{name}' execution timed out."}
        except Exception as e:
            logger.error(f"Error executing tool {name}: {e}", exc_info=True)
            return {"error": str(e)}

import re
from typing import Dict, Any, Optional


class TemplateEngine:
    def __init__(self):
        # Format: { template_name: { locale: template_text } }
        self.templates: Dict[str, Dict[str, str]] = {
            "welcome": {
                "en": "👋 Hello {{name}}! Welcome to {{bot_name}}. How can I assist you today?",
                "es": "👋 ¡Hola {{name}}! Bienvenido a {{bot_name}}. ¿Cómo puedo ayudarte hoy?",
                "hi": "👋 नमस्ते {{name}}! {{bot_name}} में आपका स्वागत है। मैं आपकी क्या मदद कर सकता हूँ?"
            },
            "order_status": {
                "en": "📦 Order #{{order_id}}: Status is {{status}}. Expected delivery: {{eta}}.",
                "es": "📦 Pedido #{{order_id}}: El estado es {{status}}. Entrega estimada: {{eta}}.",
            },
            "payment_success": {
                "en": "✅ Payment of {{amount}} received! Thank you for your subscription.",
                "es": "✅ ¡Pago de {{amount}} recibido! Gracias por su suscripción.",
            }
        }

    def register_template(self, name: str, locale: str, content: str):
        if name not in self.templates:
            self.templates[name] = {}
        self.templates[name][locale] = content

    def render(self, template_name: str, locale: str = "en", variables: Optional[Dict[str, Any]] = None) -> str:
        """
        Renders a template with variable substitution and locale fallback.
        """
        template_group = self.templates.get(template_name, {})
        text = template_group.get(locale) or template_group.get("en", f"[Missing template: {template_name}]")

        if not variables:
            return text

        def replace_var(match):
            var_name = match.group(1).strip()
            return str(variables.get(var_name, f"{{{{{var_name}}}}}"))

        return re.sub(r"\{\{([a-zA-Z0-9_]+)\}\}", replace_var, text)
